import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"澤山鹹","description":"周易折中 - 澤山鹹","frontmatter":{"title":"澤山鹹","description":"周易折中 - 澤山鹹"},"headers":[],"relativePath":"classics/zhezhong/037.md","filePath":"classics/zhezhong/037.md"}'),h={name:"classics/zhezhong/037.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="澤山鹹" tabindex="-1">澤山鹹 <a class="header-anchor" href="#澤山鹹" aria-label="Permalink to “澤山鹹”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>鹹序卦：“有天地，然後有萬物；有萬物，然後有男女；有男女，然後有夫婦；有夫婦，然後有父子；有父子，然後有君臣；有君臣，然後有上下；有上下，然後禮義有所錯。”天地，萬物之本。夫婦，人倫之始。所以上經首《乾》、《坤》，下經首《鹹》繼以《恆》也。天地二物，故二卦分為天地之道。男女交合而成夫婦，故《鹹》與《恆》皆二體合為夫婦之義。鹹，感也，以說為主。恆，常也，以正為本。而說之道自有正也，正之道固有說焉。巽而動，剛柔皆應，說也。《鹹》之為卦，兌上艮下，少女少男也。男女相感之深，莫如少者，故二少為《鹹》也。艮體篤實，止為誠愨之義。男女篤實以下交，女心說而上應，男感之先也。男先以誠感，則女說而應也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li>邱氏富國曰：《感》，二少相交者，夫婦之始也，所以論交感之情，故以男下女為象。男下於女，婚姻之道成矣。恆二長相承者，夫婦之終也，所以論處家之道。故以男尊女卑為象，女下於男，居室之倫正矣。損雖二少，而男不下女，則鹹感之義微，益雖二長，而女居男上，則恆久之義悖。此下經所以不首《損》、《益》而首《鹹》、《恆》與？</li></ul><p>鹹：亨，利貞，取女吉。</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>鹹，交感也。兌柔在上，艮剛在下，而交相感應。又艮止則感之專，兌說則應之至。又艮以少男下於兌之少女，男先於女，得男女之正，婚姻之時，故其卦為鹹。其佔亨而利貞，取女則吉。蓋感有必通之理。</p><p>然不以貞，則失其亨，而所為皆兇矣。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>鹹，感也。不曰感者，鹹有皆義，男女交相感也。物之相感，莫如男女，而少復甚焉。凡君臣上下，以至萬物，皆有相感之道。物之相感，則有亨通之理。君臣能相感，則君臣之道通；上下能相感，則上下之志通；以至父子、夫婦、親戚朋友，皆情意相感，則和順而亨通。事物皆然，故鹹有亨之理也。利貞，相感之道，利在於正也。不以正，則入於惡矣。如夫婦之以淫姣，君臣之以媚說，上下之以邪僻，皆相感之不以正也。取女吉，以卦才言也。卦有柔上剛下二氣感應相與，止而說，男下女之義。以此義取女，則得正而吉也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰：鹹，感也。不曰感而曰鹹，鹹皆也， 無心之感也 。無心於感者，無所不通也。感則必通，而利在於正。汎言感之道如此，取女吉，專言取女者當如是也。</li></ul><p>象曰：山上有澤，鹹；君子以虛受人</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>山上有澤，以虛而通也。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>澤性潤下，土性受潤澤。在山上而其漸潤通徹，是二物之氣相感通也。君子觀山澤通氣之象，而虛其中以受於人。夫人中虛，則能受；實則不能入矣。虛中者無我也。中無私主，則無感不通。以量而容之，擇合而受之，非聖人有感必通之道也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>崔氏憬曰：山高而降，澤下而升，山澤通氣，鹹之象也。</p></li><li><p>呂氏大臨曰：澤居下而山居高，然山能出雲而致雨者，山內虛而澤氣通也。故君子居物之上，物情交感者，亦以虛受也。</p></li><li><p>郭氏雍曰：唯虛故受，受故能感。不能感者，以不能受故也；不能受者，以不能虛故也。</p></li><li><p>胡氏炳文曰：以虛受人，無心之感也。</p></li><li><p>陳氏琛曰：山上有澤，澤以潤而感乎山，山以虛而受其感，鹹之象也。君子禮之，則虛其心以受人之感焉。蓋心無私主，有感皆通。若有一豪私意自蔽，則先入者為主，而感應之機窒矣。雖有所受，未必其所當受，而所當受者反以為不合而不之受矣。</p></li><li><p>何氏楷曰：六爻之中，一言思，三言志。思何可廢？而至於朋從，則非虛；志何可無？而末而外而隨人，則非虛。極而言之，天地以虛而感物，聖人以虛而感人心。三才之道，盡於是矣。</p></li><li><p>吳氏曰：愼曰：虛者，鹹之貞也。天地之常以其心普萬物而無心，聖人之常以其情順萬事而無情，者虛而已。君子之學，廓然大公，物來順應，所謂以虛受人也。</p></li></ul><p>彖曰：鹹，感也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>釋卦名義。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>劉氏牧曰：卦以鹹名，而彖傳以感釋其義者，聖人之旨欲明感物之無心也。</p></li><li><p>張子曰：萬物本一，故一能合異。以其能合異，故謂之感。若非有異，則無合。天地乾坤，陰陽也，二端故有感。本一故能合。</p></li><li><p>丘氏富國曰：鹹者，感也。所以感者，心也。無心者不能感，故鹹加心而為感。有心於感者，亦不能鹹感，故感去心而為鹹。鹹皆也，唯無容心於感，然後無所不感。聖人以鹹名卦，而彖以感釋之，所以互明其旨也。</p></li><li><p>王氏應麟曰：鹹之感無心，感以虛也；兌之說無言，說以誠也。</p></li></ul><p>柔上而剛下，二氣感應以相與，止而說，男下女，是以亨利貞，取女吉也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以卦體、卦德、卦象釋卦辭，或以卦變言柔上剛下之義。曰鹹自旅來，柔上居六，剛下居五也，亦通。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>鹹之義感也。在卦則柔爻上而剛爻下。柔上變剛而成兌，剛下變柔而成艮。陰陽相交為男女交感之義，又兌女在上，艮男居下，亦柔上剛下也。陰陽二氣相感相應而和合，是相與也。止而說，止於說為堅愨之意，艮止於下，篤誠相下也；兌說於上，和說相應也。以男下女，和之至也。相感之道如此，是以能亨通而得正。取女如是，則吉也。卦才如此，大率感道利於正也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏肅曰：山澤以氣通，男女以禮感。男下女，初婚之所以為禮，取女之所以為吉也。</p></li><li><p>馮氏當可曰：柔上剛下，感應相與，所以為亨；止而說，所以利貞；男下女，所以取女吉也。</p></li><li><p>王氏申子曰：止而說者，謂艮止不動而意氣自相和說，乃所謂感。不止而動，則是出於作為，非感也。故六爻皆欲其靜。</p></li><li><p>蔡氏清曰：卦體、卦德、卦象三段意，皆歸於鹹之一字內。而所謂亨利貞取女吉者，義蓋從此而出。故本義以通釋卦名卦辭。</p></li></ul><p>天地感而萬物化生，聖人感人心而天下和平，觀其所感，而天地萬物之情可見矣</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>極言感通之理。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>既言男女相感之義，復推極感道以盡天地之理。天地二氣交感而化生萬物，聖人至誠以感億兆之心而天下和平。天下之心所以和平，由聖人感之也。觀天地交感化生萬物之理，與聖人感人心致和平之道，則天地萬物之情可見矣。感通之理，知道者默而觀之可也。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張子曰：能通天下之志者為能感人心。聖人同乎人而無我，故和平天下莫盛於感人心。</p></li><li><p>鄭氏汝諧曰：天地萬物雖異位，其氣則一；聖人億兆雖異勢，其誠則一。觀其所感，而其情可見者，感生於情也。情出於正，然後知感通之理。</p></li><li><p>張氏清子曰：寂然不動，性也；感而遂通，情也。於其所感而觀之，而天地萬物之情可得而見矣。</p></li></ul><p>初六：鹹其拇</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>拇，足大指也。鹹以人身取象，感於最下，鹹拇之象也。感之尚淺，欲進未能，故不言吉凶。此卦雖主於感，然六爻皆宜靜而不宜動也。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>初六在下卦之下，與四相感。以微處初，其感未深，豈能動於人？故如人拇之動，未足以進也。拇，足大指。人之相感，有淺深輕重之異，識其時𫝑，則所處不失其宜矣。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類問：鹹內卦艮止也，何以皆說動？曰：艮雖是止，然鹹有交感之義，都是要動，所以都說動。卦體雖說動，然才動便不吉。</p></li><li><p>蔡氏清曰：“鹹其拇”，辭意若曰“感以其拇也”。諸爻皆同。</p></li><li><p>又曰：本義雲，此卦雖主於感，然六爻皆宜靜而不宜動。此即以虛受人之理。大傳曰：“寂然不動，感而遂通天下之故。”程子曰：“廓然而大公，物來而順應。”周子所謂“主靜”，朱子所謂“鑑空衡平”，及先儒所謂“無心之感”者，皆謂此也。</p></li></ul><p>象曰：鹹其拇，志在外也</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>初志之動，感於四也，故曰在外。志雖動而感未深，如拇之動，未足以進也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>虞氏翻曰：志在外，謂四也。</p></li><li><p>孔氏穎逹曰：與四相應，所感在外。</p></li><li><p>俞氏琰曰：初與四感應以相與，則志之所之在於外矣。</p></li></ul><p>六二：鹹其腓，兇，居吉。</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>腓，足肚也。欲行則先自動，躁妄而不能固守者也。二當其處，又以陰柔不能固守，故取其象。然有中正之德，能居其所，故其佔動兇而靜吉也。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>二以陰在下，與五為應，故設鹹腓之戒。腓，足肚，行則先動，足乃舉之，非如腓之自動也。二若不守道，待上之求而如腓之動，則躁妄自失，所以兇也。安其居而不動，以待上之求，則得進退之道而吉也。二中正之人，以其在鹹而應五，故為此戒。復雲“居吉”，若安其分，不自動，則吉也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏弼曰：鹹道轉進，離拇升腓。腓，體動躁者也。感物以躁，兇之道也。由躁故兇，居則吉矣。處不乘剛，故可以居而獲吉。</li></ul><p>象曰：雖兇居吉，順不害也</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>二居中得正，所應又中正，其才本善。以其在鹹之時，質柔而上應，故戒以先動求君則兇，居以自守則吉。象復明之雲：“非戒之不得相感，唯順理則不害。”謂守道不先動也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li>顧氏象德曰：雖兇而居則吉者，蓋能順理以為感，不為躁動害也。居非專靜，特不妄動而已。</li></ul><p>九三：鹹其股，執其隨，往吝。</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>股，隨足而動，不能自專者也。執者，主當持守之意。下二爻皆欲動者，三亦不能自守而隨之往，則吝矣。故其象佔如此。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>九三以陽居剛，有剛陽之才而為主於內，居下之上，是宜自得於正道以感於物。而乃應於上六，陽好上而說陰，上居感說之極，故三感而從之。股者在身之下，足之上，不能自由，隨身而動者也，故以為象。言九三不能自主，隨物而動，如股然。其所執守者，隨於物也。剛陽之才，感於所說而隨之，如此而往，可羞吝也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏宗傳曰：九三處下體之上，所謂股也。三雖艮體，然以陽居陽，又有應在上，非能止也。故曰“鹹其股”。夫股隨上體而動者也。以剛過之才，不能為主於內，而其所秉執者，在於隨上體而動焉，則躁動而失正矣。故曰“往吝”。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>執其隨，本義以為隨下二爻，程傳以為隨上。然隨之為義，取於雁行相從，則以三為隨四者近是。證之隨卦，初剛隨二柔，五剛隨上柔，可見也。蓋四者心位也，心動則形隨之。而三直股位，與四相近而相承，故有“鹹其股，執其隨”之象。證之艮卦，以三為心位，六二亦曰“不拯其隨”，可見也。夫心固身之主也，然心動而形輒隨之，亦非制外飬中之道。推之人事，則如臣子之詭隨容順皆是也。以三之德不中正，故如此。</p><p>象曰：鹹其股，亦不處也；志在隨人，所執下也</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>言“亦”者，因前二爻皆欲動而云也。二爻陰躁，其動也宜；九三陽剛，居止之極，宜靜而動，可吝之甚也。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>雲“亦”者，蓋象辭本不與易相比，自作一處。故諸爻之象辭意有相續者，此言“亦”者承上爻辭也。上雲“鹹其拇，志在外也；雖兇居吉，順不害也。”鹹其股，亦不處也。前二陰爻皆有感而動，三雖陽爻亦然，故云“亦不處也”。不處謂動也。有陽剛之質而不能自主，志反在於隨人，是所操執者卑下之甚也。</p><p>九四：貞吉悔亡，憧憧往來，朋從爾思。</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>九四居股之上、脢之下，又當三陽之中心，鹹之主也。心之感物，當正而固，乃得其理。今九四乃以陽居陰，為失其正而不能固，故因佔設戒。以為能正而固，則吉而悔亡。若憧憧往來，不能正固而累於私感，則其朋類從之，不復能及遠矣。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>感者，人之動也，故皆就人身取象。拇取在下而動之微，腓取先動，股取其隨。九四無所取，直言感之道，不言鹹。其心感，乃心也。四在中而居上，當心之位，故為感之主而言感之道。貞正則吉而悔亡。感不以正，則有悔也。又四說體居陰而應初，故戒於貞。感之道，無所不通，有所私系，則害於感通，乃有悔也。聖人感天下之心，如寒暑雨暘，無不通無不應者，亦貞而已矣。貞者，虛中無我之謂也。憧憧往來，朋從爾思。夫貞一則所感無不通，若往來憧憧然，用其私心以感物，則思之所及者，有能感而動，所不及者不能感也。是其朋類，則從其思也。以有系之私心既主於一隅一事，豈能廓然無所不通乎？</p><p>繫辭曰：“天下何思何慮？天下同歸而殊塗，一致而百慮。天下何思何慮？”夫子因鹹極論感通之道。夫以思慮之私心感物，所感狹矣。天下之理一也，塗雖殊而其歸則同，慮雖百而其致則一。雖物有萬殊，事有萬變，統之以一，則無能違也。故貞其意，則窮天下無不感通焉。故曰“天下何思何慮”。用其思慮之私心，豈能無所不感也？日往則月來，月往則日來，日月相推而明生焉。寒往則暑來，暑往則寒來，寒暑相推而歲成焉。往者屈也，來者信也，屈信相感而利生焉。此以往來屈信，明感應之理。屈則有信，信則有屈，所謂感應也。故日月相推而明生，寒暑相推而歲成，功用由是而成。故曰“屈信相感而利生焉”。感動也，有感必有應。凡有動皆為感，感則必有應，所應復為感，感復有應，所以不已也。尺蠖之屈以求信也，龍蛇之蟄以存身也，精義入神以致用也，利用安身以崇德也。過此以往，未之或知也。前雲屈信之理矣，復取物以明之。尺蠖之行，先屈而後信，蓋不屈則無信，信而後有屈。觀尺蠖，則知感應之理矣。龍蛇之藏，所以存息其身而後能奮迅也，不蟄則不能奮矣。動息相感，乃屈信也。君子潛心精微之義，入於神妙，所以致其用也。潛心精微，積也；致用，施也。積與施，乃屈信也。利用安身以崇德也，承上文致用而言。利其施用，安處其身，所以崇大其德業也。所為合理，則事正而身安。聖人能事盡於此矣。故云“過此以往，未之或知也”。窮神知化，德之盛也。既雲“過此以往，未之或知”，更以此語終之，雲“窮極至神之妙，知化育之道德之至盛也，無加於此矣”。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>程子曰：天地之常，以其心普萬物而無心；聖人之常，以其情順萬事而無情。故君子之學，莫若廓然而大公，物來而順應。故曰“貞吉悔亡，憧憧往來，朋從爾思”。</p></li><li><p>楊氏時曰：九四，脢之下，股之上，心之位也。不言心，心無不該，不可以位言也。</p></li><li><p>朱子語類：問：鹹九四，“傳說虛心貞一，處全似敬”。 曰：“蓋嘗有此語，曰‘敬，心之貞也’”。 問：“憧憧往來，朋從爾思”，莫是此感彼應，憧憧是添一個心否？ 曰：“往來固是感應，憧憧是一心方欲感他，一心又欲他來應，如‘正其義便欲謀其利，明其道便欲計其功’。又如‘赤子入井之時，此心方怵惕要去救他，又欲他父母道我好’。這便是憧憧之病”。 又云：“憧憧往來，朋從爾思”。聖人未嘗不教人思，只是不可憧憧。這便是私了。感應自有個自然底道理，何必思他？若是義理，則不可不思。 問：“往來”是心中憧憧然往來，猶言“往來於懷”否？ 曰：“非也”。 又問：“是憧憧於往來之閒否？” 曰：“亦非也。只是對那日往則月來底說。那個是自然之往來，此憧憧者是加私意不好底往來。憧憧只是加一個忙迫底心，不能順自然之理。方往時又便要來，方來時又便要往，只是一個忙”。 問：“憧憧往來”如霸者以私心感人，便要人應；“自然往來”如王者，我感之也無心，而感其應我也無心而應，周遍公溥，無所私系。 曰：“也是如此”。又 問：“此以私而感彼，非以私而應，只是應之者有限量否？” 曰：“也是以私而應，如我以私惠及人少，閒被我之惠者則以我為恩，不被我之惠者則不以我為恩矣”。</p></li><li><p>問：鹹九四，“傳說虛心貞一，處全似敬”。 曰：“蓋嘗有此語，曰‘敬，心之貞也’”。</p></li><li><p>問：“憧憧往來，朋從爾思”，莫是此感彼應，憧憧是添一個心否？ 曰：“往來固是感應，憧憧是一心方欲感他，一心又欲他來應，如‘正其義便欲謀其利，明其道便欲計其功’。又如‘赤子入井之時，此心方怵惕要去救他，又欲他父母道我好’。這便是憧憧之病”。</p></li><li><p>又云：“憧憧往來，朋從爾思”。聖人未嘗不教人思，只是不可憧憧。這便是私了。感應自有個自然底道理，何必思他？若是義理，則不可不思。</p></li><li><p>問：“往來”是心中憧憧然往來，猶言“往來於懷”否？ 曰：“非也”。</p></li><li><p>又問：“是憧憧於往來之閒否？” 曰：“亦非也。只是對那日往則月來底說。那個是自然之往來，此憧憧者是加私意不好底往來。憧憧只是加一個忙迫底心，不能順自然之理。方往時又便要來，方來時又便要往，只是一個忙”。</p></li><li><p>問：“憧憧往來”如霸者以私心感人，便要人應；“自然往來”如王者，我感之也無心，而感其應我也無心而應，周遍公溥，無所私系。 曰：“也是如此”。又</p></li><li><p>問：“此以私而感彼，非以私而應，只是應之者有限量否？” 曰：“也是以私而應，如我以私惠及人少，閒被我之惠者則以我為恩，不被我之惠者則不以我為恩矣”。</p></li><li><p>胡氏炳文曰：“寂然不動，心之體；感而遂通，心之用。憧憧往來，已失其寂然不動之體，安能感而遂通天下之故？貞吉悔亡，無心之感也，何思何慮之有？憧憧往來，私矣”。</p></li><li><p>林氏希元曰：以“憧憧往來”反觀九四之貞，只是往來付之無心爾。蓋盡吾所感之道，而人之應與否皆所不計也。此便是正而固。“憧憧往來”是把個往來放在心上，切切然不能放下，故曰“何思何慮”，言其不消如此。 又曰：“貞者，施己之感不必人之應也。惟不必人之應，則不私己之感，其應者亦感，其不應者亦感，無一人之不感，亦無一人之不應，故吉而悔亡”。“憧憧往來者，施己之感必人之應也。惟必人之應，則私己之感，應者則感，不應者則不感，而其應之亦惟其感者即應，不感者則不應矣。故‘朋從爾思’。蓋‘憧憧往來’是思也，‘朋’則思之所及者。以其思之所及，故從而目之曰‘朋’，猶雲‘朋黨’也”。</p></li><li><p>又曰：“貞者，施己之感不必人之應也。惟不必人之應，則不私己之感，其應者亦感，其不應者亦感，無一人之不感，亦無一人之不應，故吉而悔亡”。“憧憧往來者，施己之感必人之應也。惟必人之應，則私己之感，應者則感，不應者則不感，而其應之亦惟其感者即應，不感者則不應矣。故‘朋從爾思’。蓋‘憧憧往來’是思也，‘朋’則思之所及者。以其思之所及，故從而目之曰‘朋’，猶雲‘朋黨’也”。</p></li></ul><p>象曰：貞吉悔亡，未感害也；憧憧往來，未光大也</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>感害，言不正而感則有害也。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>貞則吉而悔亡，未為私感所害也。系私應則害於感矣。憧憧往來，以私心相感，感之道狹矣，故云“未光大也”。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li>陸氏九淵曰：鹹九四一爻，聖人以其當心之位，其言感通為尤至。曰“貞吉悔亡”，而象以為“未感害也”，蓋未為私感所害，則心之本然無適而不正，無感而不通。曰“憧憧往來，朋從爾思”，而象以為“未光大也”，蓋憧憧往來之私心，其所感必狹，從其思者獨其私朋而已。聖人之洗心，其諸以滌去憧憧往來之私，而全其本然之正也。與此所以退藏於密，而能同乎民，交乎物，而不墮於膠焉溺焉之一偏者也。</li></ul><p>九五：鹹其脢，無悔。</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>脢，背肉也，在心上而相背，不能感物而無私系。九五適當其處，故取其象，而戒佔者以能如是，則雖不能感物，而亦可以無悔也。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>九居尊位，當以至誠感天下，而應二比上。若系二而說上，則偏私淺狹，非人君之道。豈能感天下乎？脢，背肉也，與心相背，而所不見也。言能背其私心，感非其所見，而說者，則得人君感天下之正而無悔也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰：馬融雲：“脢，背也。”鄭康成雲：“脢，脊肉也。”王肅雲：“脢在背而夾脊。”諸說不同，大體皆在心上。</p></li><li><p>王氏宗傳曰：上六處鹹之末，以口舌為容悅之道。五或以其近己也，比而說之。脢，背肉也，與心相背者也。戒之使背其心之所向，則無親狎之悔矣。</p></li></ul><p>象曰：鹹其脢，志末也</p><h3 id="本義-12" tabindex="-1">本義 <a class="header-anchor" href="#本義-12" aria-label="Permalink to “本義”">​</a></h3><p>志末，謂不能感物。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>戒使背其心而鹹脢者，為其存心淺末，系二而說上，感於私慾也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>李氏鼎祚曰：末猶上也。五比於上，故鹹其脢，志末者謂五志感於上也。</p></li><li><p>朱氏震曰：卦以初為本，上為末。</p></li><li><p>王氏宗傳曰：謂五有鹹其脢之象者，以其志意之所向在於一卦之末，故欲鹹其脢以背去之也。</p></li><li><p>何氏楷曰：謂五志在與上相感也。繫辭曰：“其初難知，其上易知。”本末也。《大過》彖傳“本末弱”，末指上六可知矣。</p></li></ul><p>上六：鹹其輔頰舌</p><h3 id="本義-13" tabindex="-1">本義 <a class="header-anchor" href="#本義-13" aria-label="Permalink to “本義”">​</a></h3><p>輔、頰、舌，皆所以言者，而在身之上。上六以陰居說之終，處鹹之極，感人以言而無其實，又兌為口舌，故其象如此。兇咎可知。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>上陰柔而說，體為說之主，又居感之極，是其欲感物之極也。故不能以至誠感物，而發見於口舌之間，小人女子之常態也，豈能動於人乎？不直雲口，而云輔頰舌，亦猶今人謂口過曰唇吻、曰頰舌也。輔頰舌皆所用以言也。</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰：輔頰舌者，所以為語之具也。鹹其輔頰舌，則滕口說也。憧憧往來，猶未光大，況在滕口，薄可知也。</p></li><li><p>郭氏忠孝曰：《易》稱近取諸身，獨鹹、艮二卦言之為詳，而其成終有特異。豈非鹹極於說，艮終於止耶？觀“艮其輔，言有序”為可知矣。</p></li></ul><p>象曰：鹹其輔頰舌，滕口說也</p><h3 id="本義-14" tabindex="-1">本義 <a class="header-anchor" href="#本義-14" aria-label="Permalink to “本義”">​</a></h3><p>滕，滕通用。</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>唯至誠為能感人，乃以柔說騰揚於口舌，言說豈能感於人乎？</p><h3 id="集說-16" tabindex="-1">集說 <a class="header-anchor" href="#集說-16" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏弼曰：鹹道轉末，故在口舌言語而已。</li></ul><p>總論</p><ul><li><p>鄭氏汝諧曰：卦言感應之理，六爻皆不純乎吉，何也？卦合而言之，爻析而言之。天地感而萬物化生，聖人感人心而天下和平，鹹之全也。六爻之所感不同，鹹之偏也。自初至上，皆以人身為象，囿於有我，安能無所不感乎？</p></li><li><p>易氏祓曰：鹹，感也。感以心為主，而偏體皆所感之一。初鹹其拇，二鹹其腓，三鹹其股，五鹹其脢，上鹹其輔頰舌，皆感其偏體者也。所感出於心，故皆以“鹹”字明之。九四在上下之閒，其位在心，故不言鹹而言所感之道。</p></li><li><p>丘氏富國曰：鹹六爻以身取象，上卦象上體，下卦象下體。初在下體之下為拇，二在下體之中為腓，三在下體之上為股，此下卦三爻之序也。四在上體之下為心，五在上體之中為脢，上在上體之上為口，此上卦三爻之序也。</p></li><li><p>龔氏煥曰：鹹以人身取象，與艮卦相類。但鹹感，艮止，感者動，而止者靜。故鹹諸爻不如艮吉多而兇少。</p></li></ul>',122)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
